  `hra` decimal(15,2) DEFAULT 0.00,
  `da` decimal(10,2) NOT NULL DEFAULT 0.00,
  `conveyance` decimal(15,2) DEFAULT 0.00,
  `medical_allowance` decimal(15,2) DEFAULT 0.00,
