  KEY `idx_ss_status` (`status`),
  KEY `idx_ss_dept` (`department`),
  KEY `idx_salary_structures_tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
